\set ON_ERROR_STOP on
begin;
update coverage_rule set clause = 'Преамбула «а также при кариесе, пульпите, некариозных»'
 where clause like 'Преамбула «при кариесе, пульпите%' and document_id = (select id from program_document where id::text like '48e6565f%');
with d as (select id, insurance_company_id from program_document where id::text like '48e6565f%')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause)
select d.id, d.insurance_company_id, '«Специализированная стоматология» (Ингосстрах, актуальная)', v.sc, v.sp, v.vd, v.ct, v.la, v.cl
from d cross join (values
('стоматология-профилактика','герметизация фиссур','covered',null,null,'п. 1.1.15'),
('стоматология-терапия','восстановление разрушенной коронки штифт','conditional','только если необходимость возникла из-за травмы ЧЛО в срок договора (или предыдущих договоров при непрерывном страховании по этой программе)',null,'п. 1.1.16'),
('протезирование','зубопротезные услуги металлические металлокерамические коронки','conditional','только металлические и металлокерамические коронки и только при травме ЧЛО в срок действия договора (учитывается непрерывное страхование)',null,'п. 1.1.17'),
('документы-справки','экспертиза нетрудоспособности листок 095у','covered','открытие, продление и закрытие листка нетрудоспособности и/или справки 095/у',null,'п. 1.1.18'),
('общие-условия','обращение в клинику из договора','conditional','услуги — в медицинской организации, указанной в договоре страхования',null,'п. 2.1'),
('общие-условия','помощь в выборе клиники','needs_approval','застрахованный может обратиться в СПАО «Ингосстрах» за помощью в выборе организации; организацию определяет страховщик',null,'п. 2.3 – 2.4'),
('общие-условия','просроченная задолженность по франшизе','needs_approval','при просрочке оплаты франшизы страховщик вправе перевести все услуги в режим согласования каждой услуги; при неоплате — взыскание через суд',null,'п. 2.6.5 – 2.6.6'),
('общие-условия','услуги рекомендованные врачом но не предусмотренные программой','excluded','обязательств по организации и оплате таких услуг у страховщика не возникает',null,'п. 2.7'),
('общие-условия','противопоказания к услугам программы','excluded','если услуги программы противопоказаны — страховщик не обязан организовать иные услуги или выплатить деньгами',null,'п. 2.8'),
('общие-условия','замена клиники по независящим причинам','needs_approval','при невозможности оказания услуг клиникой из договора выбор иной организации делает страховщик, застрахованный обязан следовать решению',null,'п. 2.9')
) as v(sc, sp, vd, ct, la, cl);
select count(*) as ing_prog from coverage_rule where document_id = (select id from program_document where id::text like '48e6565f%');
commit;
